use std::fs::File;
use std::io::Write;

use integration_tester::ALL_TESTS;

/// This is meant to be run on the host, not wasm.
fn main() {
    let mut file = File::create("tests.gen.py").unwrap();
    writeln!(file, "#!/usr/bin/env python3").unwrap();
    writeln!(file, "").unwrap();
    writeln!(
        file,
        "# Generated by integration-tester/src/bin/gen_py_tests.rs"
    )
    .unwrap();
    writeln!(file, "import unittest").unwrap();
    writeln!(file, "import urllib.request").unwrap();
    writeln!(file, "").unwrap();
    writeln!(file, "BASE_URL = 'http://localhost:8787/'").unwrap();
    writeln!(file, "").unwrap();
    writeln!(file, "class TestIntegration(unittest.TestCase):").unwrap();
    writeln!(file, "").unwrap();
    for &test in ALL_TESTS {
        writeln!(file, "  def {}(self):", test).unwrap();
        writeln!(
            file,
            "    with urllib.request.urlopen(f'{{BASE_URL}}{test}') as response:"
        )
        .unwrap();
        writeln!(
            file,
            "      self.assertEqual(response.read().decode('utf-8'), '{test} passed')"
        )
        .unwrap();
        writeln!(file, "").unwrap();
    }
    writeln!(file, "").unwrap();
    writeln!(file, "if __name__ == '__main__':").unwrap();
    writeln!(file, "    unittest.main()").unwrap();
}
